1	package vault
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"io/fs"
8		"os"
9		"path/filepath"
10		"sort"
11		"strings"
12	)
13	
14	// Snapshot is an immutable record of every name mapping in the repository at
15	// creation time. It only references existing content objects; no artifact
16	// bytes are copied.
17	type Snapshot struct {
18		Name    string           `json:"name"`
19		Entries map[string]Entry `json:"entries"`
20	}
21	
22	// SnapshotInfo summarizes a saved snapshot for listing.
23	type SnapshotInfo struct {
24		Name  string
25		Count int
26	}
27	
28	// CreateSnapshot records the current name mapping under the given snapshot
29	// name. The snapshot is written to a temporary file and renamed into place,
30	// so a crash leaves either the complete snapshot or none at all.
31	func (s *Store) CreateSnapshot(name string) (Snapshot, error) {
32		if err := validateName(name); err != nil {
33			return Snapshot{}, err
34		}
35		var snap Snapshot
36		err := s.withLock(true, func() error {
37			if err := s.initLocked(); err != nil {
38				return err
39			}
40			idx, err := s.load()
41			if err != nil {
42				return fmt.Errorf("cannot snapshot: current index is unreadable: %w", err)
43			}
44			path := s.snapshotPath(name)
45			if _, err := os.Stat(path); err == nil {
46				return fmt.Errorf("snapshot %q already exists", name)
47			} else if !errors.Is(err, os.ErrNotExist) {
48				return err
49			}
50			snap = Snapshot{Name: name, Entries: idx.Entries}
51			return s.saveSnapshot(path, snap)
52		})
53		if err != nil {
54			return Snapshot{}, err
55		}
56		return snap, nil
57	}
58	
59	// ListSnapshots returns every saved snapshot sorted by name. A repository
60	// with no snapshots yields an empty list.
61	func (s *Store) ListSnapshots() ([]SnapshotInfo, error) {
62		infos := []SnapshotInfo{}
63		err := s.withLock(false, func() error {
64			dir := s.snapshotsDir()
65			err := filepath.WalkDir(dir, func(path string, d fs.DirEntry, err error) error {
66				if err != nil {
67					return err
68				}
69				if d.IsDir() || !strings.HasSuffix(d.Name(), ".json") {
70					return nil
71				}
72				rel, err := filepath.Rel(dir, path)
73				if err != nil {
74					return err
75				}
76				name := strings.TrimSuffix(filepath.ToSlash(rel), ".json")
77				data, err := os.ReadFile(path)
78				if err != nil {
79					return err
80				}
81				var snap Snapshot
82				if err := json.Unmarshal(data, &snap); err != nil {
83					return fmt.Errorf("snapshot %q is corrupted: %w", name, err)
84				}
85				infos = append(infos, SnapshotInfo{Name: name, Count: len(snap.Entries)})
86				return nil
87			})
88			if errors.Is(err, os.ErrNotExist) {
89				return nil
90			}
91			return err
92		})
93		if err != nil {
94			return nil, err
95		}
96		sort.Slice(infos, func(i, j int) bool { return infos[i].Name < infos[j].Name })
97		return infos, nil
98	}
99	
100	// RestoreSnapshot replaces the current name mapping with the snapshot's
101	// recorded mapping in a single atomic index write. The current index is never
102	// read, so restore works even when it is corrupted. Every referenced object
103	// is checked for existence, size, and SHA-256 before the mapping is swapped;
104	// any failure leaves the current mapping and all snapshots untouched.
105	func (s *Store) RestoreSnapshot(name string) error {
106		if err := validateName(name); err != nil {
107			return err
108		}
109		return s.withLock(true, func() error {
110			if err := s.initLocked(); err != nil {
111				return err
112			}
113			data, err := os.ReadFile(s.snapshotPath(name))
114			if errors.Is(err, os.ErrNotExist) {
115				return fmt.Errorf("snapshot %q not found", name)
116			}
117			if err != nil {
118				return err
119			}
120			var snap Snapshot
121			if err := json.Unmarshal(data, &snap); err != nil {
122				return fmt.Errorf("snapshot %q is corrupted: %w", name, err)
123			}
124			if snap.Entries == nil {
125				snap.Entries = map[string]Entry{}
126			}
127			for key, entry := range snap.Entries {
128				if entry.Name != key {
129					return fmt.Errorf("snapshot %q is corrupted: entry %q is filed under %q", name, entry.Name, key)
130				}
131				if err := validateName(entry.Name); err != nil {
132					return fmt.Errorf("snapshot %q is corrupted: invalid entry name %q", name, entry.Name)
133				}
134				if !isDigest(entry.Digest) {
135					return fmt.Errorf("snapshot %q is corrupted: entry %q has digest %q, want 64 lowercase hex characters", name, entry.Name, entry.Digest)
136				}
137				if entry.Size < 0 {
138					return fmt.Errorf("snapshot %q is corrupted: entry %q has negative size %d", name, entry.Name, entry.Size)
139				}
140			}
141			for _, entry := range snap.Entries {
142				if err := s.verifyObject(entry); err != nil {
143					return fmt.Errorf("cannot restore snapshot %q: object for %q: %w", name, entry.Name, err)
144				}
145			}
146			return s.save(index{Entries: snap.Entries})
147		})
148	}
149	
150	func (s *Store) saveSnapshot(path string, snap Snapshot) error {
151		data, err := json.MarshalIndent(snap, "", "  ")
152		if err != nil {
153			return err
154		}
155		data = append(data, '\n')
156		if err := s.ensureSnapshotParent(path); err != nil {
157			return err
158		}
159		dir := filepath.Dir(path)
160		tmp, err := os.CreateTemp(dir, ".snapshot-*")
161		if err != nil {
162			return err
163		}
164		tmpName := tmp.Name()
165		defer os.Remove(tmpName)
166		if _, err := tmp.Write(data); err != nil {
167			tmp.Close()
168			return err
169		}
170		if err := tmp.Close(); err != nil {
171			return err
172		}
173		return os.Rename(tmpName, path)
174	}
175	
176	// ensureSnapshotParent creates the parent directories of a snapshot record one
177	// component at a time, refusing to follow symbolic links. Without this a nested
178	// snapshot name such as "evil/x" could be redirected through a pre-created
179	// snapshots/evil symlink to write outside the repository.
180	func (s *Store) ensureSnapshotParent(path string) error {
181		base := s.snapshotsDir()
182		rel, err := filepath.Rel(base, filepath.Dir(path))
183		if err != nil {
184			return err
185		}
186		if rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
187			return errors.New("snapshot path escapes the snapshots directory")
188		}
189		// The base directory itself must exist and be a real directory, even for a
190		// top-level snapshot (a freshly initialized repository has no snapshots/).
191		cur := base
192		if err := ensureRealDir(cur); err != nil {
193			return err
194		}
195		if rel == "." {
196			return nil
197		}
198		for _, component := range strings.Split(rel, string(filepath.Separator)) {
199			next := filepath.Join(cur, component)
200			if err := ensureRealDir(next); err != nil {
201				return err
202			}
203			cur = next
204		}
205		return nil
206	}
207	
208	// ensureRealDir makes sure path is a real directory, creating it if absent,
209	// and refuses an existing symlink or non-directory.
210	func ensureRealDir(path string) error {
211		info, err := os.Lstat(path)
212		switch {
213		case errors.Is(err, os.ErrNotExist):
214			if err := os.Mkdir(path, 0o755); err != nil && !errors.Is(err, os.ErrExist) {
215				return err
216			}
217			info, err = os.Lstat(path)
218			if err != nil {
219				return err
220			}
221		case err != nil:
222			return err
223		}
224		if info.Mode()&os.ModeSymlink != 0 {
225			return fmt.Errorf("repository path %q is a symbolic link", path)
226		}
227		if !info.IsDir() {
228			return fmt.Errorf("repository path %q is not a directory", path)
229		}
230		return nil
231	}
232	
233	func (s *Store) snapshotsDir() string { return filepath.Join(s.root, "snapshots") }
234	
235	func (s *Store) snapshotPath(name string) string {
236		return filepath.Join(s.snapshotsDir(), filepath.FromSlash(name)+".json")
237	}
238	
239	func isDigest(digest string) bool {
240		if len(digest) != 64 {
241			return false
242		}
243		for _, c := range digest {
244			if (c < '0' || c > '9') && (c < 'a' || c > 'f') {
245				return false
246			}
247		}
248		return true
249	}
