41		}
42	
43		// Overwrite one artifact and add another after the snapshot.
44		if _, err := store.Put("releases/app.txt", v2); err != nil {
45			t.Fatal(err)
46		}
47		if _, err := store.Put("extra.txt", v2); err != nil {
48			t.Fatal(err)
