1	package vault
2	
3	import (
4		"crypto/sha256"
5		"encoding/base64"
6		"encoding/hex"
7		"encoding/json"
8		"errors"
9		"fmt"
10		"os"
11		"path/filepath"
12		"reflect"
13		"sort"
14	)
15	
16	// ExportResult summarizes a successful snapshot export.
17	type ExportResult struct {
18		Name    string
19		Entries int
20		Objects int
21	}
22	
23	// ImportResult summarizes a successful snapshot import.
24	type ImportResult struct {
25		Name       string
26		Entries    int
27		NewObjects int
28	}
29	
30	// ExportSnapshot writes the named snapshot, together with the content objects
31	// it needs, to output as a portable package.
32	//
33	// Without a base the package is complete: every referenced object is carried,
34	// and a digest shared by several entries is carried once. With base set to the
35	// name of another snapshot in the same repository, the package still records
36	// the target's complete mapping but only carries objects the base does not
37	// reference; an importer can only apply it on top of an identical base.
38	//
39	// Every object the target references is re-read and checked for recorded size
40	// and SHA-256, including objects omitted from a delta, so a corrupt snapshot
41	// record or a missing/damaged object never produces a successful package.
42	//
43	// The output location is held to the same rules as a download: it must be
44	// outside the source repository (judged on actual locations, through
45	// symlinks, and before the file exists), its parent directory must already
46	// exist, an existing output must be a regular file that is not hard-linked to
47	// any index, snapshot record, lock file, or content object, and the package
48	// is committed through a descriptor pinned to the resolved parent directory,
49	// so a parent swapped for a symlink into the repository while the export runs
50	// is detected at commit time and can never redirect the package onto a
51	// repository file. The package is assembled in memory and written to a
52	// temporary file in that directory before an atomic rename: a failed export
53	// never creates or alters the output file.
54	func (s *Store) ExportSnapshot(name, base, output string) (ExportResult, error) {
55		if err := validateName(name); err != nil {
56			return ExportResult{}, err
57		}
58		if base != "" {
59			if err := validateName(base); err != nil {
60				return ExportResult{}, err
61			}
62		}
63		if output == "" {
64			return ExportResult{}, errors.New("output is required")
65		}
66		// Export reads an existing, initialized repository; it never creates one.
67		// The root and index are checked before taking the lock (withLockOpts
68		// passes createRoot=false so even the root directory is not materialized),
69		// and re-checked while holding the lock.
70		rootInfo, err := os.Stat(s.root)
71		switch {
72		case errors.Is(err, os.ErrNotExist):
73			return ExportResult{}, fmt.Errorf("repository %q does not exist; run init first", s.root)
74		case err != nil:
75			return ExportResult{}, err
76		case !rootInfo.IsDir():
77			return ExportResult{}, fmt.Errorf("repository root %q is not a directory", s.root)
78		}
79		if _, err := os.Stat(s.indexPath()); errors.Is(err, os.ErrNotExist) {
80			return ExportResult{}, fmt.Errorf("repository %q is not initialized; run init first", s.root)
81		} else if err != nil {
82			return ExportResult{}, err
83		}
84		var result ExportResult
85		err = s.withLockOpts(true, false, func() error {
86			if _, err := os.Stat(s.indexPath()); errors.Is(err, os.ErrNotExist) {
87				return fmt.Errorf("repository %q is not initialized; run init first", s.root)
88			} else if err != nil {
89				return err
90			}
91			// Validate the destination before reading any object or staging a
92			// temporary file, and hold the pinned parent directory until commit.
93			absOut, mode, pin, err := s.checkOutputSafe(output)
94			if err != nil {
95				return err
96			}
97			defer pin.Close()
98	
99			target, err := s.loadSnapshotRecord(name)
100			if err != nil {
101				return err
102			}
103			pkg := &Package{
104				Format:   packageFormat,
105				Version:  packageVersion,
106				Snapshot: target,
107				Objects:  []PackageObject{},
108			}
109			var baseSnap Snapshot
110			if base != "" {
111				var err error
112				baseSnap, err = s.loadSnapshotRecord(base)
113				if err != nil {
114					return fmt.Errorf("cannot use base snapshot: %w", err)
115				}
116				pkg.Base = &baseSnap
117			}
118	
119			// Verify every object the target references, reading each once. This
120			// includes objects the delta omits because the base references them:
121			// certifying the delta requires those to be intact too. Only objects
122			// the base does not reference are carried. Digests are processed in
123			// sorted order so the package layout and any failure message are
124			// deterministic.
125			carry := digestsReferenced(target.Entries)
126			if base != "" {
127				for digest := range digestsReferenced(baseSnap.Entries) {
128					delete(carry, digest)
129				}
130			}
131			for _, digest := range sortedDigests(target.Entries) {
132				content, size, err := s.readVerifiedObject(digest, target.Entries)
133				if err != nil {
134					return fmt.Errorf("snapshot %q references unusable object %s: %w", name, digest, err)
135				}
136				if _, included := carry[digest]; !included {
137					continue
138				}
139				pkg.Objects = append(pkg.Objects, PackageObject{
140					Digest: digest,
141					Size:   size,
142					Data:   base64.StdEncoding.EncodeToString(content),
143				})
144			}
145	
146			data, err := marshalPackage(pkg)
147			if err != nil {
148				return err
149			}
150			if err := s.writeOutputPackage(pin, absOut, data, mode); err != nil {
151				return err
152			}
153			result = ExportResult{Name: name, Entries: len(target.Entries), Objects: len(pkg.Objects)}
154			return nil
155		})
156		if err != nil {
157			return ExportResult{}, err
158		}
159		return result, nil
160	}
161	
162	// writeOutputPackage stages the package as a complete temporary file inside
163	// the pinned parent directory and commits it via Store.commitOutput, which
164	// revalidates the destination immediately before the atomic rename. On any
165	// failure the temporary file is removed and an existing output is never
166	// touched.
167	func (s *Store) writeOutputPackage(pin *parentPin, absOut string, data []byte, mode os.FileMode) error {
168		tmp, tmpBase, err := createTempIn(pin, ".package-")
169		if err != nil {
170			return fmt.Errorf("cannot create temporary file for output: %w", err)
171		}
172		committed := false
173		defer func() {
174			if !committed {
175				removeTempIn(pin, tmpBase)
176			}
177		}()
178		if err := tmp.Chmod(mode); err != nil {
179			tmp.Close()
180			return fmt.Errorf("cannot prepare output file: %w", err)
181		}
182		if _, err := tmp.Write(data); err != nil {
183			tmp.Close()
184			return fmt.Errorf("cannot write output %q: %w", absOut, err)
185		}
186		if err := tmp.Sync(); err != nil {
187			tmp.Close()
188			return fmt.Errorf("cannot write output %q: %w", absOut, err)
189		}
190		if err := tmp.Close(); err != nil {
191			return fmt.Errorf("cannot write output %q: %w", absOut, err)
192		}
193		if err := s.commitOutput(pin, tmpBase, absOut); err != nil {
194			return err
195		}
196		committed = true
197		_ = syncDirectory(pin.f)
198		return nil
199	}
200	
201	// ImportSnapshot imports a snapshot package produced by ExportSnapshot into an
202	// initialized repository.
203	//
204	// Import only adds the package's snapshot and any missing content objects; it
205	// never changes the current name mapping or any existing snapshot or object.
206	// A delta package is accepted only when the destination already contains a
207	// snapshot with the base name and byte-identical entry metadata, and every
208	// object the delta omits is present and intact. Healthy objects already in the
209	// destination are reused; re-importing a package whose snapshot is already
210	// present with identical metadata succeeds without creating a second copy. A
211	// same-named snapshot with different metadata is refused.
212	//
213	// All validation and reuse happens before anything is written. New objects
214	// land as complete files via temp-file-and-rename, and the snapshot record is
215	// renamed into place only after every object the mapping references has been
216	// verified, so a crash or write failure leaves at most unreferenced complete
217	// objects that a later gc removes and a retry succeeds; a partially imported
218	// snapshot can never be observed.
219	func (s *Store) ImportSnapshot(file string) (ImportResult, error) {
220		if file == "" {
221			return ImportResult{}, errors.New("file is required")
222		}
223		data, err := os.ReadFile(file)
224		if err != nil {
225			return ImportResult{}, err
226		}
227		pkg, err := decodePackage(data)
228		if err != nil {
229			return ImportResult{}, err
230		}
231		// Import targets an initialized repository; it never creates one the way
232		// mutating artifact commands do.
233		rootInfo, err := os.Stat(s.root)
234		switch {
235		case errors.Is(err, os.ErrNotExist):
236			return ImportResult{}, fmt.Errorf("repository %q does not exist; run init first", s.root)
237		case err != nil:
238			return ImportResult{}, err
239		case !rootInfo.IsDir():
240			return ImportResult{}, fmt.Errorf("repository root %q is not a directory", s.root)
241		}
242		var result ImportResult
243		err = s.withLock(true, func() error {
244			if _, err := os.Stat(s.indexPath()); errors.Is(err, os.ErrNotExist) {
245				return fmt.Errorf("repository %q is not initialized; run init first", s.root)
246			} else if err != nil {
247				return err
248			}
249			if err := rejectLinkedDirs(s.root); err != nil {
250				return err
251			}
252	
253			// A delta must sit on an exactly matching base: same snapshot name and
254			// identical entry metadata. A merely same-named snapshot, or objects
255			// that happen to share digests, is not a base.
256			if pkg.Base != nil {
257				existing, err := s.loadSnapshotRecord(pkg.Base.Name)
258				if err != nil {
259					return fmt.Errorf("delta base snapshot %q is unavailable: %w", pkg.Base.Name, err)
260				}
261				if !snapshotsEqual(existing, *pkg.Base) {
262					return fmt.Errorf("delta base snapshot %q does not match the package base", pkg.Base.Name)
263				}
264				if err := s.verifyReferencedObjects(pkg.Base.Name, existing.Entries); err != nil {
265					return fmt.Errorf("delta base snapshot %q is not fully present: %w", pkg.Base.Name, err)
266				}
267			}
268	
269			// A same-named destination snapshot is either identical metadata or a
270			// collision. A collision is refused before anything is staged.
271			targetPath := s.snapshotPath(pkg.Snapshot.Name)
272			identicalSnapshot := false
273			if existing, statErr := os.Lstat(targetPath); statErr == nil {
274				if existing.Mode()&os.ModeSymlink != 0 {
275					return fmt.Errorf("snapshot path %q is a symbolic link", targetPath)
276				}
277				current, err := s.loadSnapshotRecord(pkg.Snapshot.Name)
278				if err != nil {
279					return fmt.Errorf("snapshot %q already exists and is unusable: %w", pkg.Snapshot.Name, err)
280				}
281				if !snapshotsEqual(current, pkg.Snapshot) {
282					return fmt.Errorf("snapshot %q already exists with different metadata; refusing to overwrite", pkg.Snapshot.Name)
283				}
284				identicalSnapshot = true
285				// Fast path: everything the published snapshot needs is already
286				// present and healthy, so the import is a no-op.
287				if s.verifyReferencedObjects(pkg.Snapshot.Name, pkg.Snapshot.Entries) == nil {
288					result = ImportResult{Name: pkg.Snapshot.Name, Entries: len(pkg.Snapshot.Entries), NewObjects: 0}
289					return nil
290				}
291				// Otherwise fall through: a carried object that is merely missing
292				// can be staged to complete an earlier interrupted import, while a
293				// damaged existing object still aborts below.
294			} else if !errors.Is(statErr, os.ErrNotExist) {
295				return statErr
296			}
297	
298			objects, err := pkg.materialize()
299			if err != nil {
300				return err
301			}
302	
303			// Phase 1, no writes: classify every carried object. Existing files
304			// must be healthy and are reused; a damaged one aborts the import and
305			// is reported by digest.
306			toAdd := make([]objectContent, 0, len(objects))
307			for _, obj := range objects {
308				path := s.objectPath(obj.digest)
309				info, err := os.Lstat(path)
310				switch {
311				case err == nil:
312					if info.Mode()&os.ModeSymlink != 0 {
313						return fmt.Errorf("object %s: object path is a symbolic link", obj.digest)
314					}
315					if !info.Mode().IsRegular() {
316						return fmt.Errorf("object %s: object path is not a regular file", obj.digest)
317					}
318					if _, _, err := s.readVerifiedObject(obj.digest, pkg.Snapshot.Entries); err != nil {
319						return fmt.Errorf("object %s already present but damaged: %w", obj.digest, err)
320					}
321				case errors.Is(err, os.ErrNotExist):
322					toAdd = append(toAdd, obj)
323				default:
324					return err
325				}
326			}
327	
328			// Phase 2: stage missing objects as complete, content-addressed files.
329			// A failure here leaves only unreferenced complete objects behind; a
330			// retry reuses them and finishes the import.
331			for _, obj := range toAdd {
332				if err := s.stageObject(obj.digest, obj.content); err != nil {
333					return err
334				}
335			}
336	
337			// Phase 3: the published mapping must be fully restorable. This covers
338			// reused objects, newly staged ones, and everything omitted by a delta.
339			if err := s.verifyReferencedObjects(pkg.Snapshot.Name, pkg.Snapshot.Entries); err != nil {
340				return err
341			}
342	
343			// Phase 4: publish the snapshot record last (unless an identical one is
344			// already published). This rename is the commit point; before it a new
345			// imported snapshot simply does not exist.
346			if !identicalSnapshot {
347				if err := s.saveSnapshot(targetPath, pkg.Snapshot); err != nil {
348					return err
349				}
350			}
351			result = ImportResult{Name: pkg.Snapshot.Name, Entries: len(pkg.Snapshot.Entries), NewObjects: len(toAdd)}
352			return nil
353		})
354		if err != nil {
355			return ImportResult{}, err
356		}
357		return result, nil
358	}
359	
360	// loadSnapshotRecord reads and fully validates one stored snapshot: it must
361	// parse, carry a non-null entries mapping, record the same name it is filed
362	// under, and contain only valid entry records.
363	func (s *Store) loadSnapshotRecord(name string) (Snapshot, error) {
364		path := s.snapshotPath(name)
365		info, err := os.Lstat(path)
366		if errors.Is(err, os.ErrNotExist) {
367			return Snapshot{}, fmt.Errorf("snapshot %q not found", name)
368		}
369		if err != nil {
370			return Snapshot{}, err
371		}
372		if info.Mode()&os.ModeSymlink != 0 {
373			return Snapshot{}, fmt.Errorf("snapshot %q is a symbolic link", name)
374		}
375		if !info.Mode().IsRegular() {
376			return Snapshot{}, fmt.Errorf("snapshot %q is not a regular file", name)
377		}
378		data, err := os.ReadFile(path)
379		if err != nil {
380			return Snapshot{}, err
381		}
382		var snap Snapshot
383		if err := json.Unmarshal(data, &snap); err != nil {
384			return Snapshot{}, fmt.Errorf("snapshot %q is corrupted: %w", name, err)
385		}
386		if snap.Entries == nil {
387			return Snapshot{}, fmt.Errorf("snapshot %q is corrupted: missing entries mapping", name)
388		}
389		if snap.Name != name {
390			return Snapshot{}, fmt.Errorf("snapshot %q is corrupted: recorded name %q does not match its location", name, snap.Name)
391		}
392		for key, entry := range snap.Entries {
393			if err := validateEntryRecord(key, entry); err != nil {
394				return Snapshot{}, fmt.Errorf("snapshot %q is corrupted: %w", name, err)
395			}
396		}
397		return snap, nil
398	}
399	
400	// verifyReferencedObjects checks each distinct referenced digest once against
401	// the stored object's size and SHA-256.
402	func (s *Store) verifyReferencedObjects(snapshotName string, entries map[string]Entry) error {
403		for _, digest := range sortedDigests(entries) {
404			if _, _, err := s.readVerifiedObject(digest, entries); err != nil {
405				return fmt.Errorf("object %s needed by snapshot %q: %w", digest, snapshotName, err)
406			}
407		}
408		return nil
409	}
410	
411	// readVerifiedObject reads a content object and returns its bytes, confirming
412	// its SHA-256 digest and the size recorded for it in the given entries.
413	func (s *Store) readVerifiedObject(digest string, entries map[string]Entry) ([]byte, int64, error) {
414		path := s.objectPath(digest)
415		info, err := os.Lstat(path)
416		if err != nil {
417			return nil, 0, err
418		}
419		if info.Mode()&os.ModeSymlink != 0 {
420			return nil, 0, errors.New("object path is a symbolic link")
421		}
422		if !info.Mode().IsRegular() {
423			return nil, 0, errors.New("object path is not a regular file")
424		}
425		content, err := os.ReadFile(path)
426		if err != nil {
427			return nil, 0, err
428		}
429		sum := sha256.Sum256(content)
430		if actual := hex.EncodeToString(sum[:]); actual != digest {
431			return nil, 0, fmt.Errorf("content checksum is %s", actual)
432		}
433		// Every entry referencing this digest must agree on the size; a content
434		// hash fixes the byte count, so a disagreement is a corrupt record.
435		for _, entry := range entries {
436			if entry.Digest == digest && int64(len(content)) != entry.Size {
437				return nil, 0, fmt.Errorf("content is %d bytes, record for %q says %d", len(content), entry.Name, entry.Size)
438			}
439		}
440		return content, int64(len(content)), nil
441	}
442	
443	// stageObject writes one missing object to a temp file and renames it into
444	// place. The content digest was verified when the package was decoded, so the
445	// final file is complete before it ever appears under its digest name.
446	func (s *Store) stageObject(digest string, content []byte) error {
447		tmp, err := os.CreateTemp(filepath.Join(s.root, "objects"), ".import-*")
448		if err != nil {
449			return err
450		}
451		tmpName := tmp.Name()
452		defer os.Remove(tmpName)
453		if _, err := tmp.Write(content); err != nil {
454			tmp.Close()
455			return fmt.Errorf("object %s: %w", digest, err)
456		}
457		if err := tmp.Close(); err != nil {
458			return fmt.Errorf("object %s: %w", digest, err)
459		}
460		if err := os.Rename(tmpName, s.objectPath(digest)); err != nil {
461			return fmt.Errorf("object %s: %w", digest, err)
462		}
463		return nil
464	}
465	
466	// rejectLinkedDirs makes sure an import can never stage files outside the
467	// repository through a replaced objects or snapshots directory.
468	func rejectLinkedDirs(root string) error {
469		for _, dir := range []string{filepath.Join(root, "objects"), filepath.Join(root, "snapshots")} {
470			if err := ensureRealDir(dir); err != nil {
471				return err
472			}
473		}
474		return nil
475	}
476	
477	// snapshotsEqual reports whether two snapshot records carry the same snapshot
478	// name and identical metadata for every entry.
479	func snapshotsEqual(a, b Snapshot) bool {
480		return reflect.DeepEqual(a.Entries, b.Entries) && a.Name == b.Name
481	}
482	
483	func sortedDigests(entries map[string]Entry) []string {
484		seen := map[string]struct{}{}
485		for _, entry := range entries {
486			seen[entry.Digest] = struct{}{}
487		}
488		out := make([]string, 0, len(seen))
489		for digest := range seen {
490			out = append(out, digest)
491		}
492		sort.Strings(out)
493		return out
494	}
495

