package vault

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func writeSnapshotFile(t *testing.T, root, name, body string) {
	t.Helper()
	path := filepath.Join(root, "snapshots", filepath.FromSlash(name)+".json")
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(path, []byte(body), 0o644); err != nil {
		t.Fatal(err)
	}
}

func TestScratchRestoreNameMismatchMultilevel(t *testing.T) {
	root := filepath.Join(t.TempDir(), "vault")
	store := New(root)
	if _, err := store.Put("keep.txt", writeFile(t, "keep me")); err != nil {
		t.Fatal(err)
	}
	// Record filed under releases/stable.json but naming only "stable".
	body := `{"name":"stable","entries":{}}` + "\n"
	writeSnapshotFile(t, root, "releases/stable", body)
	err := store.RestoreSnapshot("releases/stable")
	if err == nil {
		t.Fatal("restore of basename-only record should fail")
	}
	if !strings.Contains(err.Error(), "releases/stable") {
		t.Fatalf("error must name chosen snapshot: %v", err)
	}
	entries, err := store.List()
	if err != nil {
		t.Fatal(err)
	}
	if len(entries) != 1 || entries[0].Name != "keep.txt" {
		t.Fatalf("current mapping changed: %+v", entries)
	}

	// Another name entirely.
	writeSnapshotFile(t, root, "releases/stable", `{"name":"releases/other","entries":{}}`+"\n")
	if err := store.RestoreSnapshot("releases/stable"); err == nil {
		t.Fatal("restore of differently named record should fail")
	}
	if entries, err := store.List(); err != nil || len(entries) != 1 {
		t.Fatalf("mapping changed: %+v %v", entries, err)
	}

	// Correct full multi-level name, empty entries -> success, list empty.
	writeSnapshotFile(t, root, "releases/stable", `{"name":"releases/stable","entries":{}}`+"\n")
	if err := store.RestoreSnapshot("releases/stable"); err != nil {
		t.Fatal(err)
	}
	if entries, err := store.List(); err != nil || len(entries) != 0 {
		t.Fatalf("entries=%+v err=%v", entries, err)
	}
}

func TestScratchRestoreRejectsMissingEntries(t *testing.T) {
	bodies := map[string]string{
		"missing entries":   `{"name":"s"}` + "\n",
		"null entries":      `{"name":"s","entries":null}` + "\n",
		"null body":         `null` + "\n",
		"empty object body": `{}` + "\n",
		"garbage":           `{broken`,
	}
	for label, body := range bodies {
		t.Run(label, func(t *testing.T) {
			root := filepath.Join(t.TempDir(), "vault")
			store := New(root)
			if _, err := store.Put("keep.txt", writeFile(t, "keep me")); err != nil {
				t.Fatal(err)
			}
			writeSnapshotFile(t, root, "s", body)
			err := store.RestoreSnapshot("s")
			if err == nil {
				t.Fatal("expected failure")
			}
			if !strings.Contains(err.Error(), `"s"`) {
				t.Fatalf("error must name snapshot %q: %v", "s", err)
			}
			if entries, err := store.List(); err != nil || len(entries) != 1 || entries[0].Name != "keep.txt" {
				t.Fatalf("mapping changed: %+v err=%v", entries, err)
			}
			if strings.Contains(strings.ToLower(err.Error()), "restored") {
				t.Fatalf("failure must not look like success: %v", err)
			}
		})
	}
}

func TestScratchRestorePreservesCorruptIndexOnFailure(t *testing.T) {
	root := filepath.Join(t.TempDir(), "vault")
	store := New(root)
	if _, err := store.Put("a.txt", writeFile(t, "good")); err != nil {
		t.Fatal(err)
