	if err := os.WriteFile(filepath.Join(root, "index.json"), []byte("{not json"), 0o644); err != nil {
		t.Fatal(err)
	}
	snapPath := filepath.Join(root, "snapshots", "stable.json")
	original, err := os.ReadFile(snapPath)
	if err != nil {
